import json,re
c=json.load(open('cur.json'));T=c['T'];F=c['F'];idx=c['idx']
def u(s): return len(s.encode('utf-16-le'))//2
E=[]
def rng_(s_txt,e_txt):
    a=T.index(s_txt); b=T.index(e_txt,a)+len(e_txt); assert set(F[a:b])=={'.'},(s_txt[:30],set(F[a:b])); return idx[a],idx[b-1]+1
noise=("The noise was set from the data before the cue, where the decoder z carries no memory signal and therefore reflects read-out noise alone. We matched two of its properties. The first is its size. Like the pre-cue z, η has unit variance (the standard deviation of pre-cue z was 1.06). The second is how slowly it changes. Because z is computed in 100 ms windows stepped by 10 ms, consecutive points share most of their spikes, so the noise at two points Δt apart is correlated by 1 − Δt/100 ms for Δt < 100 ms, and not at all beyond. We generated this part of η as white noise averaged in the same overlapping windows. In the data, however, z remained correlated beyond 100 ms, because the decoder output also drifts slowly from trial to trial. We captured this drift with a constant offset added to each trial, whose share of the variance, ρ, was set to the correlation of pre-cue z between time points 200 ms apart, which is far enough that the windows do not overlap (ρ = 0.35 for all neurons, 0.09 for the most selective neurons and 0.11 for random neurons; Supplementary Fig. 1c). Thus η(t) = √(1 − ρ) ε(t) + √ρ ξ, where ε is the window-averaged white noise and ξ the per-trial offset, both with unit variance.")
E.append((*rng_('The noise was constrained by the data before the cue','which are largest for decoders using all neurons.'),noise))
E.append((*rng_('Decoding strength increases steeply and monotonically with c, so c is well determined.','so c is well determined.'),
          'Decoding strength increases steeply and monotonically with c, so c is well determined (Supplementary Fig. 1e).'))
E.append((*rng_('Model statistics were computed from 2,112 simulated trials','(792 per evaluation during fitting).'),
          'Model statistics were computed from 2,112 simulated trials, four times the average number of correct trials per session (528), so that they are estimated more precisely than in any single session. During fitting, each evaluation used 792 trials (one and a half sessions) to keep the optimization fast.'))
val=("Because this read-out replaces a real decoder by a simple formula, we tested whether the procedure above recovers the On/Off statistics of a real decoder in synthetic data where the ground truth is known (Supplementary Fig. 1f–h). We used the fitted model to generate spikes and decoded them with the unchanged data pipeline. The model was simulated for two cue locations, A and B. When A was cued, pool A was the cued pool and pool B the uncued one, and the reverse when B was cued, which gives the decoder two classes to discriminate, as in the data. "
"The pool rates drove 330 Poisson neurons, the average number of units recorded per session (329). 30% of them followed pool A or pool B (half each) and the rest were untuned. Baseline rates were lognormal with a median of 5 Hz, and all neurons shared a per-trial gain, which produces slow trial-to-trial drift as in the data. We simulated 70 trials per cue location, close to the number of correct trials per location in a session, and 8 synthetic sessions at each of three tuning strengths. The tuning strength was chosen so that the decoder's decoding strength matched that of the data's random-20, all-unit and top-20 decoders (1.4, 2.1 and 4.0). The fraction of tuned neurons matters only through this decoding strength, which the tuning strength sets. "
"We then applied to the synthetic decoder output exactly the calibration used for the data. The gain c was set from its decoding strength, the noise share ρ from its pre-cue autocorrelation, and the resulting read-out c·Δr + η was compared with the decoder on the same trials. The read-out's z correlated with the decoder's as closely as two runs of the decoder on independent spikes from the same rates, and it reproduced the number and fraction of Off states. It undercounted On states by about one per trial, because the decoder's z fluctuates faster than η, and adding a small white-noise component matched to these fast fluctuations removed the difference. "
"Finally, controls on the fitted model showed that On/Off statistics change smoothly with the gain and with ρ, and that noise alone produces Off states but almost no On states (Supplementary Fig. 1i).")
E.append((*rng_('Because this read-out is a simplification of a real decoder','(Supplementary Fig. 1i).'),val))
R=[]
for s,e,n in sorted(E,key=lambda x:-x[0]):
    R+=[{"deleteContentRange":{"range":{"startIndex":s,"endIndex":e}}},{"insertText":{"location":{"index":s},"text":n}}]
    for m in re.finditer(r'\b(?:On|Off)(?:/(?:On|Off))?\b',n):
        p=s+u(n[:m.start()]); R.append({"updateTextStyle":{"range":{"startIndex":p,"endIndex":p+u(m.group(0))},"textStyle":{"italic":True},"fields":"italic"}})
print(c['rev']); print(json.dumps(R))
